import{_ as a,o as t,c as n,a5 as o}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"Local Run Architecture (docker/compose/ + Host Services)","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/local-run-architecture.md","filePath":"architecture/local-run-architecture.md"}'),s={name:"architecture/local-run-architecture.md"};function d(l,e,c,r,i,p){return t(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="local-run-architecture-docker-compose-host-services" tabindex="-1">Local Run Architecture (<code>docker/compose/</code> + Host Services) <a class="header-anchor" href="#local-run-architecture-docker-compose-host-services" aria-label="Permalink to &quot;Local Run Architecture (\`docker/compose/\` + Host Services)&quot;">​</a></h1><p>&gt; Navigation: <a href="./../">← Knowledge Base Hub</a> · <a href="./README.html">← Architecture Index</a> · <a href="./technical-overview.html">Technical Overview</a> · <a href="./../operations/deployment-acct134.html">Production Deployment</a></p><p>Describes how BrandHub&#39;s local Docker Compose v2 infrastructure stacks (<code>docker/</code>) integrate with host-run microservices, web SPA, and Expo mobile clients during daily development and full-stack integration testing.</p><hr><h2 id="_1-modular-docker-compose-include-graph" tabindex="-1">1. Modular Docker Compose <code>include:</code> Graph <a class="header-anchor" href="#_1-modular-docker-compose-include-graph" aria-label="Permalink to &quot;1. Modular Docker Compose \`include:\` Graph&quot;">​</a></h2><p>Located in <code>brandhub-infrastructure/docker/</code>, the local stack uses Docker Compose v2.20+ <code>include:</code> composition across two primary launchers (<code>docker/run_dev.bat</code> and <code>docker/run_dev_ai.bat</code>, also driven by the <code>run-brandhub</code> desktop GUI) and <strong>6 reusable fragments</strong> in <code>docker/compose/shared/</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docker/</span></span>
<span class="line"><span>├── run_dev.bat ─────────► compose/run-compose.bat dev    ──► compose/dev/compose.yaml</span></span>
<span class="line"><span>│                                                               ├── shared/databases.yaml</span></span>
<span class="line"><span>│                                                               └── shared/cache-broker.yaml</span></span>
<span class="line"><span>├── run_dev_ai.bat ──────► compose/run-compose.bat dev-ai ──► compose/dev-ai/compose.yaml</span></span>
<span class="line"><span>│                                                               ├── ../dev/compose.yaml</span></span>
<span class="line"><span>│                                                               └── shared/chroma.yaml</span></span>
<span class="line"><span>├── clear_brandhub.bat   (Label-scoped teardown of brandhub* containers, volumes, networks &amp; images)</span></span>
<span class="line"><span>└── compose/</span></span>
<span class="line"><span>    ├── .env.example     (121-line tracked template copied to gitignored compose/.env on first run)</span></span>
<span class="line"><span>    ├── seed-guide.md    (DataSeeder SEED_ENABLED=true &amp; database/backups/restore-* workflow)</span></span>
<span class="line"><span>    └── shared/</span></span>
<span class="line"><span>        ├── databases.yaml      # postgres:17-alpine (:5432) + mongo:7.0 (:27017) + init bind-mounts</span></span>
<span class="line"><span>        ├── cache-broker.yaml   # redis:7.2-alpine (:6379, 256mb AOF) + rabbitmq:3.12-management-alpine (:5672/:15672)</span></span>
<span class="line"><span>        ├── chroma.yaml         # chromadb/chroma:1.5.9 (127.0.0.1:8000, pinned with brandhub-ai-service)</span></span>
<span class="line"><span>        ├── neo4j.yaml          # Optional (-f): neo4j:5.26-community (:7474 HTTP / :7687 Bolt)</span></span>
<span class="line"><span>        ├── pgadmin.yaml        # Optional (-f): dpage/pgadmin4:9 (127.0.0.1:5050)</span></span>
<span class="line"><span>        └── apps.yaml           # Optional (-f): builds gateway, business, ai, publisher, crawl from sibling repos</span></span></code></pre></div><h3 id="why-infrastructure-and-app-containers-are-split" tabindex="-1">Why Infrastructure and App Containers Are Split <a class="header-anchor" href="#why-infrastructure-and-app-containers-are-split" aria-label="Permalink to &quot;Why Infrastructure and App Containers Are Split&quot;">​</a></h3><p>During active coding, engineers run <code>.\\run_dev.bat up</code> (or <code>.\\run_dev_ai.bat up</code> when working on AI/RAG) so stateful data stores run reliably in Docker while Java (<code>./mvnw spring-boot:run</code>), Python (<code>uvicorn app.main:app --reload --port 8082</code>), and React (<code>npm run dev</code>) run directly on the host with sub-second hot reload. Layering <code>-f compose/shared/apps.yaml</code> builds all 5 backend containers onto <code>brandhub-network</code> for staging-parity verification.</p><hr><h2 id="_2-container-port-volume-bootstrap-matrix" tabindex="-1">2. Container Port, Volume &amp; Bootstrap Matrix <a class="header-anchor" href="#_2-container-port-volume-bootstrap-matrix" aria-label="Permalink to &quot;2. Container Port, Volume &amp; Bootstrap Matrix&quot;">​</a></h2><p>All containers join the fixed bridge network <strong><code>brandhub-network</code></strong>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Container</th><th style="text-align:left;">Pinned Image</th><th style="text-align:left;">Host Port(s)</th><th style="text-align:left;">Named Docker Volume</th><th style="text-align:left;">First-Boot / Runtime Behavior</th></tr></thead><tbody><tr><td style="text-align:left;"><code>brandhub-postgres</code></td><td style="text-align:left;"><code>postgres:17-alpine</code></td><td style="text-align:left;"><code>5432</code></td><td style="text-align:left;"><code>brandhub-postgres-v2-data</code></td><td style="text-align:left;">Mounts <code>database/init/init-postgres-v2.sql</code> read-only (<code>97</code> tables + <code>6</code> Studio/Agency SePay plans) when volume is empty</td></tr><tr><td style="text-align:left;"><code>brandhub-mongodb</code></td><td style="text-align:left;"><code>mongo:7.0</code></td><td style="text-align:left;"><code>27017</code></td><td style="text-align:left;"><code>brandhub-mongodb-data</code></td><td style="text-align:left;">Mounts <code>database/init/init-mongo.js</code> read-only (<code>52</code> collections + <code>$jsonSchema</code> validators + indexes) when volume is empty</td></tr><tr><td style="text-align:left;"><code>brandhub-redis</code></td><td style="text-align:left;"><code>redis:7.2-alpine</code></td><td style="text-align:left;"><code>6379</code></td><td style="text-align:left;"><code>brandhub-redis-data</code></td><td style="text-align:left;">Runs <code>--requirepass</code>, <code>--appendonly yes</code>, <code>--maxmemory 256mb</code>, <code>--maxmemory-policy allkeys-lru</code></td></tr><tr><td style="text-align:left;"><code>brandhub-rabbitmq</code></td><td style="text-align:left;"><code>rabbitmq:3.12-management-alpine</code></td><td style="text-align:left;"><code>5672</code>, <code>15672</code></td><td style="text-align:left;"><code>brandhub-rabbitmq-data</code></td><td style="text-align:left;">AMQP broker (<code>:5672</code>) + Management UI (<code>http://localhost:15672</code>)</td></tr><tr><td style="text-align:left;"><code>brandhub-chromadb</code></td><td style="text-align:left;"><code>chromadb/chroma:1.5.9</code></td><td style="text-align:left;"><code>127.0.0.1:8000</code></td><td style="text-align:left;"><code>brandhub-chroma-data</code></td><td style="text-align:left;">Telemetry disabled; <code>/api/v2/heartbeat</code> TCP healthcheck</td></tr><tr><td style="text-align:left;"><code>brandhub-neo4j</code> <em>(opt)</em></td><td style="text-align:left;"><code>neo4j:5.26-community</code></td><td style="text-align:left;"><code>7474</code>, <code>7687</code></td><td style="text-align:left;"><code>brandhub-neo4j-data</code></td><td style="text-align:left;">Local Trend Knowledge Graph (<code>database/migrations/neo4j/</code> indexes)</td></tr><tr><td style="text-align:left;"><code>brandhub-pgadmin</code> <em>(opt)</em></td><td style="text-align:left;"><code>dpage/pgadmin4:9</code></td><td style="text-align:left;"><code>127.0.0.1:5050</code></td><td style="text-align:left;"><code>brandhub-pgadmin-data</code></td><td style="text-align:left;">Import <code>database/init/pgadmin-servers.json</code> to connect to <code>postgres:5432</code></td></tr></tbody></table><p>&gt; <strong>Existing Volume Catch-Up</strong>: Docker <code>/docker-entrypoint-initdb.d/*</code> scripts run <strong>only</strong> on empty volumes. On an older local volume, apply ordered scripts from <code>database/migrations/</code> (or <code>database/scripts/patch-update-running-db.sql</code>), or run <code>docker\\clear_brandhub.bat</code> for a clean slate (see <a href="./../guides/team-workflow-guide.html">Team Workflow Guide</a>).</p><hr><h2 id="_3-host-application-port-dependency-topology" tabindex="-1">3. Host Application Port &amp; Dependency Topology <a class="header-anchor" href="#_3-host-application-port-dependency-topology" aria-label="Permalink to &quot;3. Host Application Port &amp; Dependency Topology&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>brandhub-web (Vite 8 :3000)  &amp;  brandhub-mobile-app (Expo 58 Metro :8090)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        │ HTTP /api/v1/**  +  WebSocket STOMP /ws/chat &amp; /ws/tasks</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>brandhub-api-gateway (:8080) ──► Redis (:6379, JWT blacklist + rate limit)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├──► brandhub-business-service (:8081)</span></span>
<span class="line"><span>        │       ├──► PostgreSQL (:5432) + MongoDB (:27017) + Redis (:6379)</span></span>
<span class="line"><span>        │       ├──► RabbitMQ (:5672, publisher.job.exchange) ──► brandhub-publisher-service (:8083)</span></span>
<span class="line"><span>        │       └──► brandhub-ai-service (:8082, X-Internal-Key)</span></span>
<span class="line"><span>        │               ├──► ChromaDB (:8000) + Neo4j (:7687) + Redis (:6379)</span></span>
<span class="line"><span>        │               └──► brandhub-crawl (:8084) / Vast.ai GPU Worker (:10200)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        └──► brandhub-publisher-service (:8083, GET /api/v1/social/{fb,ig,tiktok,threads}/{authorize,callback})</span></span></code></pre></div><h3 id="mobile-client-networking-brandhub-mobile-app" tabindex="-1">Mobile Client Networking (<code>brandhub-mobile-app</code>) <a class="header-anchor" href="#mobile-client-networking-brandhub-mobile-app" aria-label="Permalink to &quot;Mobile Client Networking (\`brandhub-mobile-app\`)&quot;">​</a></h3><ul><li><strong>Metro Bundler Port (<code>8090</code>)</strong>: Moved off Expo&#39;s default <code>8081</code> so it never collides with <code>brandhub-business-service</code> (<code>:8081</code>).</li><li><strong>Gateway Endpoint (<code>EXPO_PUBLIC_API_BASE_URL</code>)</strong>: <ul><li><strong>Android Emulator (AVD)</strong>: <code>http://10.0.2.2:8080</code></li><li><strong>iOS Simulator</strong>: <code>http://localhost:8080</code></li><li><strong>Physical Device (Expo Go / Dev Client)</strong>: <code>http://&lt;host-lan-ipv4&gt;:8080</code> (ensure Windows Firewall allows inbound TCP <code>8080</code> and <code>8090</code> on Private networks).</li></ul></li></ul>`,19)])])}const b=a(s,[["render",d]]);export{u as __pageData,b as default};
